// === Tab: mySketch ===
/**
 * GENERADOR "TD-EMULATOR" V2 - INTERACTIVO
 * PURO JAVASCRIPT PARA OPENPROCESSING
 */

let particulas = [];
let numParticulas = 400; 
let feedbackBuffer;      
let zOff = 0;            

// Controles UI
let sliderRuido, sliderFuerza, sliderFeedback;
let mostrarUI = true;

// Configuración de Parámetros
let parametros = {
  escalaRuido: 0.005,
  fuerzaRuido: 2.5,
  velocidadEvolucion: 0.002,
  escalaFeedback: 1.003, 
  alphaDesvanecimiento: 0.03
};

function setup() {
  createCanvas(windowWidth, windowHeight);
  colorMode(HSB, 360, 100, 100, 1);

  feedbackBuffer = createGraphics(windowWidth, windowHeight);
  feedbackBuffer.colorMode(HSB, 360, 100, 100, 1);
  feedbackBuffer.background(5, 100, 10); 

  for (let i = 0; i < numParticulas; i++) {
    particulas.push(new Particula());
  }

  // Inicializar Sliders
  let margin = 35;

  sliderRuido = createSlider(0.001, 0.02, 0.005, 0.001);
  sliderRuido.position(margin + 120, margin + 85);
  sliderRuido.style('width', '100px');

  sliderFuerza = createSlider(0.5, 8.0, 2.5, 0.1);
  sliderFuerza.position(margin + 120, margin + 115);
  sliderFuerza.style('width', '100px');

  sliderFeedback = createSlider(0.98, 1.05, 1.003, 0.001);
  sliderFeedback.position(margin + 120, margin + 145);
  sliderFeedback.style('width', '100px');

  textFont('monospace');
  background(5, 100, 10);
}

function draw() {
  // 1. Leer Sliders en tiempo real
  parametros.escalaRuido = sliderRuido.value();
  parametros.fuerzaRuido = sliderFuerza.value();
  parametros.escalaFeedback = sliderFeedback.value();

  // FASE DE FEEDBACK TOP
  feedbackBuffer.push();
  feedbackBuffer.translate(width / 2, height / 2);
  feedbackBuffer.scale(parametros.escalaFeedback);

  let rotacionInteractiva = map((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), 0, width, -0.05, 0.05);
  feedbackBuffer.rotate(rotacionInteractiva); 
  feedbackBuffer.translate(-width / 2, -height / 2);

  feedbackBuffer.noStroke();
  feedbackBuffer.fill(5, 100, 10, parametros.alphaDesvanecimiento);
  feedbackBuffer.rect(0, 0, width, height);
  feedbackBuffer.pop();

  // FASE DE CHOPs Y SOPs
  for (let p of particulas) {
    p.actualizar();
    p.dibujar(feedbackBuffer);
  }
  zOff += parametros.velocidadEvolucion; 

  // RENDER FINAL AL LIENZO
  image(feedbackBuffer, 0, 0);

  // UI OVERLAY 
  if (mostrarUI) {
    dibujarUI();
    sliderRuido.show();
    sliderFuerza.show();
    sliderFeedback.show();
  } else {
    sliderRuido.hide();
    sliderFuerza.hide();
    sliderFeedback.hide();
  }
}

function keyPressed() {
  if (key === 'c' || key === 'C') {
    feedbackBuffer.background(5, 100, 10);
  }
  if (key === 'h' || key === 'H') {
    mostrarUI = !mostrarUI;
  }
}

class Particula {
  constructor() {
    this.pos = createVector(random(width), random(height));
    this.vel = createVector(0, 0);
    this.colorBase = random([
      color(180, 100, 100), 
      color(300, 100, 100), 
      color(60, 100, 100)   
    ]);
    this.grosor = random(1, 3);
  }

  actualizar() {
    let angulo = noise(this.pos.x * parametros.escalaRuido, this.pos.y * parametros.escalaRuido, zOff) * TWO_PI * 4;
    let direccion = p5.Vector.fromAngle(angulo);
    direccion.mult(parametros.fuerzaRuido);

    let raton = createVector((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))));
    let vectorAtraccion = p5.Vector.sub(raton, this.pos);
    let distancia = vectorAtraccion.mag();

    if (distancia < 200) {
      vectorAtraccion.normalize();
      let fuerzaAtraccion = map(distancia, 0, 200, 2, 0); 
      vectorAtraccion.mult(fuerzaAtraccion);
      direccion.add(vectorAtraccion);
    }

    this.vel.lerp(direccion, 0.1);
    this.pos.add(this.vel);

    if (this.pos.x > width) this.pos.x = 0;
    if (this.pos.x < 0) this.pos.x = width;
    if (this.pos.y > height) this.pos.y = 0;
    if (this.pos.y < 0) this.pos.y = height;
  }

  dibujar(buffer) {
    buffer.noStroke();

    let cExterior = color(hue(this.colorBase), saturation(this.colorBase), brightness(this.colorBase), 0.05);
    buffer.fill(cExterior);
    buffer.circle(this.pos.x, this.pos.y, this.grosor * 8);

    let cMedio = color(hue(this.colorBase), saturation(this.colorBase), brightness(this.colorBase), 0.2);
    buffer.fill(cMedio);
    buffer.circle(this.pos.x, this.pos.y, this.grosor * 4);

    buffer.fill(0, 0, 100, 0.9); 
    buffer.circle(this.pos.x, this.pos.y, this.grosor);
  }
}

function dibujarUI() {
  var margin = 20;

  noStroke();
  fill(0, 0, 15, 0.85); 
  rect(margin, margin, 270, 260, 5);

  stroke(180, 100, 100, 0.5); 
  strokeWeight(1);
  noFill();
  rect(margin, margin, 270, 260, 5);

  noStroke();
  fill(0, 0, 100);
  textSize(14);
  text("NETWORK: /project/interactive", margin + 15, margin + 25);

  stroke(0, 0, 50);
  line(margin + 15, margin + 40, margin + 255, margin + 40);

  noStroke();
  textSize(12);
  fill(180, 50, 100); 

  let currentY = margin + 60;
  let lineSpace = 30;

  text(`FPS:      ${floor(frameRate())}`, margin + 15, currentY);
  currentY += lineSpace;
  text(`Ruido:`, margin + 15, currentY);
  currentY += lineSpace;
  text(`Fuerza:`, margin + 15, currentY);
  currentY += lineSpace;
  text(`Feedback:`, margin + 15, currentY);
  currentY += lineSpace + 10;

  fill(0, 0, 70);
  text(`[ MOUSE ] = Atraer & Rotar`, margin + 15, currentY);
  currentY += 20;
  text(`[ C ]     = Limpiar Buffer`, margin + 15, currentY);
  currentY += 20;
  text(`[ H ]     = Ocultar UI`, margin + 15, currentY);

  fill(120, 100, 80); 
  rect(margin, margin + 255, 270, 5, 0, 0, 5, 5);
}

function windowResized() {
  resizeCanvas(windowWidth, windowHeight);
  let tempImg = feedbackBuffer.get();
  feedbackBuffer.resizeCanvas(windowWidth, windowHeight);
  feedbackBuffer.image(tempImg, 0, 0, windowWidth, windowHeight);

  var margin = 35;
  sliderRuido.position(margin + 120, margin + 85);
  sliderFuerza.position(margin + 120, margin + 115);
  sliderFeedback.position(margin + 120, margin + 145);
}

